package com.bank.recon.service;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

// Finds all unique triplets of signed adjustments that sum to zero.
public class ReversalFinder {
    private static final Logger log = Logger.getLogger(ReversalFinder.class.getName());

    public List<List<Integer>> findZeroSumTriplets(int[] adjustments) {
        List<List<Integer>> result = new ArrayList<>();
        if (adjustments == null || adjustments.length < 3) return result;

        Arrays.sort(adjustments); // enables two-pointer + duplicate skipping

        for (int i = 0; i < adjustments.length - 2; i++) {
            if (adjustments[i] > 0) break;                  // no zero-sum possible beyond here
            if (i > 0 && adjustments[i] == adjustments[i - 1]) continue; // skip duplicate anchor

            int left = i + 1;
            int right = adjustments.length - 1;
            while (left < right) {
                int sum = adjustments[i] + adjustments[left] + adjustments[right];
                if (sum == 0) {
                    result.add(Arrays.asList(
                            adjustments[i], adjustments[left], adjustments[right]));
                    // skip duplicate pair values
                    while (left < right && adjustments[left] == adjustments[left + 1]) left++;
                    while (left < right && adjustments[right] == adjustments[right - 1]) right--;
                    left++;
                    right--;
                } else if (sum < 0) {
                    left++;   // need a larger sum
                } else {
                    right--;  // need a smaller sum
                }
            }
        }
        log.info(() -> "Found " + result.size() + " zero-sum triplet(s): " + result);
        return result;
    }
}
