package com.bank.recon;

import com.bank.recon.service.ReversalFinder;
import java.util.List;
import java.util.logging.Logger;

public class ReversalFinderDemo {
    private static final Logger log = Logger.getLogger(ReversalFinderDemo.class.getName());

    public static void main(String[] args) {
        // Signed adjustments on an account: credits positive, debits negative.
        int[] adjustments = {-1, 0, 1, 2, -1, -4};

        ReversalFinder finder = new ReversalFinder();
        List<List<Integer>> triplets = finder.findZeroSumTriplets(adjustments);

        for (List<Integer> t : triplets) {
            log.info(() -> "Cancelling trio: " + t);
        }
    }
}
